                    <img src="@ProfileAvatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <div class="avatar-url-display">
                    <label>Avatar URL</label>
                    <span class="url-text">@ProfileAvatarUrl</span>
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" class="form-control" @bind="ProfileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" class="form-control" @bind="ProfileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" class="form-control" rows="4" @bind="ProfileBio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </div>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <h2>Notification Preferences</h2>

        <div class="settings-section">
            <div class="toggle-group">
                <label class="toggle-item">
                    <span>Email Notifications</span>
                    <input type="checkbox" class="toggle-switch" @bind="EmailNotifications" />
                </label>
                <label class="toggle-item">
                    <span>Push Notifications</span>
                    <input type="checkbox" class="toggle-switch" @bind="PushNotifications" />
                </label>
                <label class="toggle-item">
                    <span>Weekly Digest</span>
                    <input type="checkbox" class="toggle-switch" @bind="WeeklyDigest" />
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in AllChannels)
                {
                    <label class="channel-item">
                        <input type="checkbox"
                               checked="@MutedChannels.Contains(channel)"
                               @onchange="() => ToggleChannelMute(channel)" />
                        <span>#@channel</span>
                        @if (MutedChannels.Contains(channel))
                        {
                            <span class="muted-badge">Muted</span>
                        }
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </div>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <h2>Security Settings</h2>

        <div class="settings-section">
            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▼" : "▶")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" class="form-control" @bind="CurrentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" class="form-control" @bind="NewPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" class="form-control" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="two-factor-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-indicator">
                    <span class="status-dot @(_securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")"></span>
                    <span>@(_securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")</span>
                </div>
                @if (_securitySettings?.LastPasswordChange.HasValue == true)
                {
                    <p class="last-change">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <div class="sessions-section">
                <h3>Active Sessions</h3>
                @if (_securitySettings?.Sessions?.Any() == true)
                {
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != _securitySettings.Sessions.First())
                                        {
                                            <button class="btn btn-sm btn-danger"
                                                    @onclick="() => RequestRevokeSession(session.Id, session.Device)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-session-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                }
                else
                {
                    <p>No active sessions found.</p>
                }
            </div>
        </div>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <h2>Appearance Settings</h2>

        <div class="settings-section">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(SelectedTheme == theme)"
                                   @onchange="() => SelectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(SelectedFontSize == size)"
                                   @onchange="() => SelectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" class="form-control" @bind="SelectedLanguage">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-item">
                    <span>Compact Mode</span>
                    <input type="checkbox" class="toggle-switch" @bind="CompactMode" />
                </label>
            </div>

            <div class="live-preview">
                <h3>Preview</h3>
                <div class="preview-box @GetPreviewClasses()">
                    <p class="preview-heading">Sample Heading</p>
                    <p class="preview-text">This is how your content will look with the selected settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </div>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"theme-{SelectedTheme.ToLower()}");
        classes.Add($"font-{SelectedFontSize.ToLower()}");
        if (CompactMode) classes.Add("compact");
        return string.Join(" ", classes);
    }
}

